/bin/bash -lc "python3 -B - <<'PY'
from hashlib import sha1
from pathlib import Path

def object_hash(kind, data):
    return sha1(f'{kind} {len(data)}\\0'.encode() + data).digest()

expected = {
    'base': '322f27a0f9b9ada9c399c4fba1ee28ff9fbd22c5',
    'head': '1ef63334bc8d5371bb869e4f326286a047397a42',
}
for directory, expected_hash in expected.items():
    data = b''
    for file in sorted(Path(directory).iterdir()):
        assert file.is_file() and not file.is_symlink() and file.stat().st_mode & 0o111 == 0
        data += f'100644 {file.name}\\0'.encode() + object_hash('blob', file.read_bytes())
    actual = object_hash('tree', data).hex()
    print(directory, actual)
    assert actual == expected_hash
PY"
